829:     {
830:         // get number of digits for a float -> text -> float round-trip
831:         static constexpr auto d = std::numeric_limits<number_float_t>::max_digits10;
832: 
833:         // the actual conversion
834:         // NOLINTNEXTLINE(cppcoreguidelines-pro-type-vararg,hicpp-vararg)
835:         std::ptrdiff_t len = (std::snprintf)(number_buffer.data(), number_buffer.size(),
836:                                              std::is_same<number_float_t, long double>::value ? "%.*Lg" : "%.*g",
837:                                              d, x);
838: 
839:         // negative value indicates an error
840:         JSON_ASSERT(len > 0);
841:         // check if buffer was large enough
842:         JSON_ASSERT(static_cast<std::size_t>(len) < number_buffer.size());
843: 
844:         // erase thousands separator
845:         if (thousands_sep != '\0')
846:         {
847:             // NOLINTNEXTLINE(readability-qualified-auto,llvm-qualified-auto): std::remove returns an iterator, see https://github.com/nlohmann/json/issues/3081
848:             const auto end = std::remove(number_buffer.begin(), number_buffer.begin() + len, thousands_sep);
849:             std::fill(end, number_buffer.end(), '\0');
850:             JSON_ASSERT((end - number_buffer.begin()) <= len);
851:             len = (end - number_buffer.begin());
852:         }
853: 
854:         // convert decimal point to '.'
855:         if (decimal_point != '\0' && decimal_point != '.')
