857:             // NOLINTNEXTLINE(readability-qualified-auto,llvm-qualified-auto): std::find returns an iterator, see https://github.com/nlohmann/json/issues/3081
858:             const auto dec_pos = std::find(number_buffer.begin(), number_buffer.end(), decimal_point);
